// Test shim: the few parts of three.js (r170, MIT) that tests/tools/bm_js.mjs
// and the BumpMesh modules it loads use, for machines with no npm registry.
// bm_js.mjs prefers a real 'three' from BumpMesh's node_modules when there is
// one. The arithmetic follows three.js r170 line by line.

export const MathUtils = { degToRad: (d) => d * Math.PI / 180, radToDeg: (r) => r * 180 / Math.PI };

export class Vector3 {
  constructor(x = 0, y = 0, z = 0) { this.isVector3 = true; this.x = x; this.y = y; this.z = z; }
  set(x, y, z) { this.x = x; this.y = y; this.z = z; return this; }
  copy(v) { this.x = v.x; this.y = v.y; this.z = v.z; return this; }
  clone() { return new Vector3(this.x, this.y, this.z); }
  add(v) { this.x += v.x; this.y += v.y; this.z += v.z; return this; }
  sub(v) { this.x -= v.x; this.y -= v.y; this.z -= v.z; return this; }
  addVectors(a, b) { this.x = a.x + b.x; this.y = a.y + b.y; this.z = a.z + b.z; return this; }
  subVectors(a, b) { this.x = a.x - b.x; this.y = a.y - b.y; this.z = a.z - b.z; return this; }
  addScaledVector(v, s) { this.x += v.x * s; this.y += v.y * s; this.z += v.z * s; return this; }
  multiplyScalar(s) { this.x *= s; this.y *= s; this.z *= s; return this; }
  divideScalar(s) { return this.multiplyScalar(1 / s); }
  negate() { this.x = -this.x; this.y = -this.y; this.z = -this.z; return this; }
  dot(v) { return this.x * v.x + this.y * v.y + this.z * v.z; }
  lengthSq() { return this.x * this.x + this.y * this.y + this.z * this.z; }
  length() { return Math.sqrt(this.lengthSq()); }
  normalize() { return this.divideScalar(this.length() || 1); }
  cross(v) { return this.crossVectors(this, v); }
  crossVectors(a, b) {
    const ax = a.x, ay = a.y, az = a.z, bx = b.x, by = b.y, bz = b.z;
    this.x = ay * bz - az * by; this.y = az * bx - ax * bz; this.z = ax * by - ay * bx;
    return this;
  }
  min(v) { this.x = Math.min(this.x, v.x); this.y = Math.min(this.y, v.y); this.z = Math.min(this.z, v.z); return this; }
  max(v) { this.x = Math.max(this.x, v.x); this.y = Math.max(this.y, v.y); this.z = Math.max(this.z, v.z); return this; }
  distanceTo(v) { return Math.hypot(this.x - v.x, this.y - v.y, this.z - v.z); }
  applyQuaternion(q) {
    const vx = this.x, vy = this.y, vz = this.z, qx = q.x, qy = q.y, qz = q.z, qw = q.w;
    const tx = 2 * (qy * vz - qz * vy), ty = 2 * (qz * vx - qx * vz), tz = 2 * (qx * vy - qy * vx);
    this.x = vx + qw * tx + qy * tz - qz * ty;
    this.y = vy + qw * ty + qz * tx - qx * tz;
    this.z = vz + qw * tz + qx * ty - qy * tx;
    return this;
  }
  fromBufferAttribute(a, i) { this.x = a.getX(i); this.y = a.getY(i); this.z = a.getZ(i); return this; }
  fromArray(a, o = 0) { this.x = a[o]; this.y = a[o + 1]; this.z = a[o + 2]; return this; }
  toArray() { return [this.x, this.y, this.z]; }
}

export class Quaternion {
  constructor(x = 0, y = 0, z = 0, w = 1) { this.isQuaternion = true; this.x = x; this.y = y; this.z = z; this.w = w; }
  set(x, y, z, w) { this.x = x; this.y = y; this.z = z; this.w = w; return this; }
  clone() { return new Quaternion(this.x, this.y, this.z, this.w); }
  copy(q) { return this.set(q.x, q.y, q.z, q.w); }
  fromArray(a, o = 0) { return this.set(a[o], a[o + 1], a[o + 2], a[o + 3]); }
  toArray() { return [this.x, this.y, this.z, this.w]; }
  invert() { this.x *= -1; this.y *= -1; this.z *= -1; return this; }   // conjugate (unit quaternions)
  length() { return Math.sqrt(this.x * this.x + this.y * this.y + this.z * this.z + this.w * this.w); }
  normalize() {
    let l = this.length();
    if (l === 0) return this.set(0, 0, 0, 1);
    l = 1 / l;
    return this.set(this.x * l, this.y * l, this.z * l, this.w * l);
  }
  multiplyQuaternions(a, b) {
    const qax = a.x, qay = a.y, qaz = a.z, qaw = a.w, qbx = b.x, qby = b.y, qbz = b.z, qbw = b.w;
    return this.set(qax * qbw + qaw * qbx + qay * qbz - qaz * qby, qay * qbw + qaw * qby + qaz * qbx - qax * qbz,
      qaz * qbw + qaw * qbz + qax * qby - qay * qbx, qaw * qbw - qax * qbx - qay * qby - qaz * qbz);
  }
  multiply(q) { return this.multiplyQuaternions(this, q); }
  premultiply(q) { return this.multiplyQuaternions(q, this); }
  setFromEuler(e) {   // order XYZ
    const c1 = Math.cos(e.x / 2), c2 = Math.cos(e.y / 2), c3 = Math.cos(e.z / 2);
    const s1 = Math.sin(e.x / 2), s2 = Math.sin(e.y / 2), s3 = Math.sin(e.z / 2);
    return this.set(s1 * c2 * c3 + c1 * s2 * s3, c1 * s2 * c3 - s1 * c2 * s3, c1 * c2 * s3 + s1 * s2 * c3, c1 * c2 * c3 - s1 * s2 * s3);
  }
}

export class Euler {
  constructor(x = 0, y = 0, z = 0, order = 'XYZ') {
    if (order !== 'XYZ') throw new Error('shim: Euler order XYZ only');
    this.x = x; this.y = y; this.z = z; this.order = order;
  }
}

export class Box3 {
  constructor() { this.min = new Vector3(Infinity, Infinity, Infinity); this.max = new Vector3(-Infinity, -Infinity, -Infinity); }
  getSize(t) { return t.subVectors(this.max, this.min); }
  getCenter(t) { return t.addVectors(this.min, this.max).multiplyScalar(0.5); }
}

export class BufferAttribute {
  constructor(array, itemSize, normalized = false) {
    this.array = array; this.itemSize = itemSize; this.count = array.length / itemSize; this.normalized = normalized;
    this.needsUpdate = false;
  }
  getX(i) { return this.array[i * this.itemSize]; }
  getY(i) { return this.array[i * this.itemSize + 1]; }
  getZ(i) { return this.array[i * this.itemSize + 2]; }
  setXYZ(i, x, y, z) { const o = i * this.itemSize; this.array[o] = x; this.array[o + 1] = y; this.array[o + 2] = z; return this; }
}
export class Float32BufferAttribute extends BufferAttribute {
  constructor(array, itemSize, normalized) { super(new Float32Array(array), itemSize, normalized); }
}

export class BufferGeometry {
  constructor() { this.isBufferGeometry = true; this.attributes = {}; this.index = null; this.boundingBox = null; }
  setAttribute(n, a) { this.attributes[n] = a; return this; }
  getAttribute(n) { return this.attributes[n]; }
  deleteAttribute(n) { delete this.attributes[n]; return this; }
  getIndex() { return this.index; }
  setIndex(i) { this.index = i; return this; }
  dispose() {}
  computeBoundingBox() {
    const b = new Box3(), p = this.attributes.position, v = new Vector3();
    for (let i = 0; i < p.count; i++) { v.fromBufferAttribute(p, i); b.min.min(v); b.max.max(v); }
    this.boundingBox = b;
  }
  applyQuaternion(q) {
    for (const n of ['position', 'normal']) {
      const a = this.attributes[n];
      if (!a) continue;
      const v = new Vector3();
      for (let i = 0; i < a.count; i++) { v.fromBufferAttribute(a, i).applyQuaternion(q); a.setXYZ(i, v.x, v.y, v.z); }
    }
    return this;
  }
  translate(x, y, z) {
    const a = this.attributes.position;
    for (let i = 0; i < a.count; i++) a.setXYZ(i, a.getX(i) + x, a.getY(i) + y, a.getZ(i) + z);
    return this;
  }
  computeVertexNormals() {   // non-indexed, as three.js r170
    if (this.index) throw new Error('shim: indexed geometry');
    const p = this.attributes.position;
    let n = this.attributes.normal;
    if (!n || n.count !== p.count) { n = new BufferAttribute(new Float32Array(p.count * 3), 3); this.setAttribute('normal', n); }
    const pA = new Vector3(), pB = new Vector3(), pC = new Vector3(), cb = new Vector3(), ab = new Vector3();
    for (let i = 0; i < p.count; i += 3) {
      pA.fromBufferAttribute(p, i); pB.fromBufferAttribute(p, i + 1); pC.fromBufferAttribute(p, i + 2);
      cb.subVectors(pC, pB); ab.subVectors(pA, pB); cb.cross(ab);
      n.setXYZ(i, cb.x, cb.y, cb.z); n.setXYZ(i + 1, cb.x, cb.y, cb.z); n.setXYZ(i + 2, cb.x, cb.y, cb.z);
    }
    const v = new Vector3();
    for (let i = 0; i < n.count; i++) { v.fromBufferAttribute(n, i).normalize(); n.setXYZ(i, v.x, v.y, v.z); }
    n.needsUpdate = true;
  }
}
